{"command":"[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
try {
  $r = Invoke-RestMethod -Uri "https://news.at.zhihu.com/api/4/news/latest" -TimeoutSec 20 -ErrorAction Stop -Headers @{ 'User-Agent' = 'Mozilla/5.0' }
  "=== 知乎日报 (日期: $($r.date)) ==="
  $r.stories | Select-Object -First 12 | ForEach-Object { "• $($_.title)" }
} catch {
  "知乎日报获取失败: $($_.Exception.Message)"
}","description":"调用知乎日报公开API获取今日新闻标题","timeout":60000}

{"command":"[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
$urls = @("https://60s.viki.moe/v2/60s", "https://api.vvhan.com/api/60s")
foreach ($u in $urls) {
  try {
    $r = Invoke-RestMethod -Uri $u -TimeoutSec 20 -Headers @{ 'User-Agent' = 'Mozilla/5.0' } -ErrorAction Stop
    $news = $r.data.news; if (-not $news) { $news = $r.news }
    if ($news) {
      "=== 每日60秒读懂世界 (来源: $u, 日期: $($r.data.date)$($r.date)) ==="
      $news | Select-Object -First 15
      break
    } else {
      "来源 $u 返回无 news 字段: $(($r | ConvertTo-Json -Compress -Depth 2))"
    }
  } catch {
    "获取失败 ($u): $($_.Exception.Message)"
  }
}","description":"尝试多个"每日60秒"新闻聚合API获取今日新闻","timeout":60000}

{"command":"[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
foreach ($p in @('TheShy','Bin_(gamer)','Chen_Ze-Bin')) {
  try {
    $r = Invoke-RestMethod -Uri "https://zh.wikipedia.org/api/rest_v1/page/summary/$p" -TimeoutSec 15 -Headers @{ 'User-Agent'='Mozilla/5.0' } -ErrorAction Stop
    "=== $p ===`n$($r.extract)`n"
  } catch { "$p 获取失败: $($_.Exception.Message)" }
}","description":"从维基百科获取TheShy和Bin的词条摘要","timeout":45000}

{"command":"[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
foreach ($q in @('TheShy 2026 现状 战队','Bin BLG 2026 LPL 上单')) {
  try {
    $r = Invoke-RestMethod -Uri "https://html.duckduckgo.com/html/?q=$([uri]::EscapeDataString($q))" -TimeoutSec 20 -Headers @{ 'User-Agent'='Mozilla/5.0' } -ErrorAction Stop
    "=== 搜索: $q ==="
    ($r -split "`n" | Select-String -Pattern 'result__a' | Select-Object -First 8) -join "`n"
    ""
  } catch { "搜索失败 ($q): $($_.Exception.Message)" }
}","description":"通过DuckDuckGo搜索两人2026年最新动态","timeout":60000}

